/* i18n layer for the pipeline UI. Loads BEFORE app.js — every other script
 * (app.js, onboarding.js, demo.js) reads translations through t()/tf().
 *
 * Russian is the source language (and the default). The header RU/EN
 * button switches the WHOLE interface: static HTML is re-applied through
 * data-i18n attributes, dynamic renders re-run through the "crew:lang"
 * event (app.js listens and re-renders everything visible).
 *
 * The numbers quoted inside tour/demo texts are the approved final-report
 * measurements — do not "improve" them here; live views read the same
 * artifacts through /api/demo/*. */
"use strict";

var LANG_KEY = "crewLang";
var LANGS = ["ru", "en", "uz", "kk", "ar"];
var RTL_LANGS = ["ar"];
/* Native self-labels for the language picker. */
var LANG_LABELS = {
  ru: "Русский", en: "English", uz: "Oʻzbekcha", kk: "Қазақша",
  ar: "العربية"
};

function uiLang() {
  var v = localStorage.getItem(LANG_KEY);
  if (LANGS.indexOf(v) >= 0) { return v; }
  /* Первый заход: язык этой установки задаёт /ui-config.js (его пишет
   * установщик через CREW_DEFAULT_LANG); без него — "ru", как раньше. */
  var d = (typeof window !== "undefined") && window.CREW_DEFAULT_LANG;
  return LANGS.indexOf(d) >= 0 ? d : "ru";
}

function setUiLang(lang) {
  localStorage.setItem(LANG_KEY, LANGS.indexOf(lang) >= 0 ? lang : "ru");
  applyI18nDom();
  document.dispatchEvent(new CustomEvent("crew:lang"));
}

/** Fill a <select> with the language options and reflect the active one.
 *  Callers wire the change handler (setUiLang(sel.value)) themselves. */
function buildLangOptions(sel) {
  if (!sel) { return; }
  var cur = uiLang();
  sel.textContent = "";
  LANGS.forEach(function (code) {
    var o = document.createElement("option");
    o.value = code;
    o.textContent = LANG_LABELS[code];
    sel.appendChild(o);
  });
  sel.value = cur;
}

/** Translate a key; falls back to Russian, then to the key itself. */
function t(key) {
  var dict = I18N[uiLang()] || {};
  if (Object.prototype.hasOwnProperty.call(dict, key)) { return dict[key]; }
  if (Object.prototype.hasOwnProperty.call(I18N.ru, key)) { return I18N.ru[key]; }
  return key;
}

/** Translate with {name} substitutions: tf("k", {n: 3}). */
function tf(key, params) {
  var s = t(key);
  Object.keys(params || {}).forEach(function (k) {
    s = s.split("{" + k + "}").join(String(params[k]));
  });
  return s;
}

/** Re-apply translations to static DOM: element text via data-i18n,
 *  attributes via data-i18n-placeholder / data-i18n-title. Also the
 *  document title and the <html lang> attribute. A customer-contour label
 *  (window.COSMOS_CONTOUR_LABEL, injected by the server from
 *  CREW_CONTOUR_LABEL) is appended to the app title as "/<label>" and must
 *  survive every language switch, hence it lives here and not in the
 *  dictionaries. */
function applyI18nDom() {
  var appTitle = t("html.title");
  if (window.COSMOS_CONTOUR_LABEL) {
    appTitle += "/" + window.COSMOS_CONTOUR_LABEL;
  }
  document.querySelectorAll("[data-i18n]").forEach(function (node) {
    var key = node.getAttribute("data-i18n");
    node.textContent = key === "html.title" ? appTitle : t(key);
  });
  document.querySelectorAll("[data-i18n-placeholder]").forEach(function (node) {
    node.setAttribute("placeholder", t(node.getAttribute("data-i18n-placeholder")));
  });
  document.querySelectorAll("[data-i18n-title]").forEach(function (node) {
    node.setAttribute("title", t(node.getAttribute("data-i18n-title")));
  });
  document.querySelectorAll("[data-i18n-label]").forEach(function (node) {
    node.setAttribute("label", t(node.getAttribute("data-i18n-label")));
  });
  document.title = appTitle;
  var lang = uiLang();
  document.documentElement.lang = lang;
  document.documentElement.dir = RTL_LANGS.indexOf(lang) >= 0 ? "rtl" : "ltr";
}

/* ================================================================ dictionary */

